// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);
        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }

        Recorder recorder = new Recorder();
        bool ok = c.transfer(from, address(recorder), tos, v);
        assertTrue(ok);

        bytes4 expectedSelector = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint256 i = 0; i < tos.length; i++) {
            assertTrue(recorder.selectorAt(i) == expectedSelector);
            assertTrue(recorder.fromAt(i) == from);
            assertTrue(recorder.toAt(i) == tos[i]);
            assertTrue(recorder.amountAt(i) == v);
        }
    }
}

contract Recorder {
    bytes4[] public selectors;
    address[] public froms;
    address[] public tos;
    uint256[] public amounts;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        selectors.push(msg.sig);
        froms.push(from);
        tos.push(to);
        amounts.push(amount);
        return true;
    }

    function recordCount() external view returns (uint256) {
        return selectors.length;
    }

    function selectorAt(uint256 i) external view returns (bytes4) {
        return selectors[i];
    }

    function fromAt(uint256 i) external view returns (address) {
        return froms[i];
    }

    function toAt(uint256 i) external view returns (address) {
        return tos[i];
    }

    function amountAt(uint256 i) external view returns (uint256) {
        return amounts[i];
    }

    fallback() external payable {
        revert();
    }
}
